import meta from "./brand-meta.json";

type Variant = keyof typeof meta;

const FILES: Record<Variant, string> = {
  "sumenep-matamadura-stacked": "/brand/sumenep-matamadura-stacked.svg",
  "sumenep-matamadura-horizontal": "/brand/sumenep-matamadura-horizontal.svg",
  "sumenep-matamadura-mono": "/brand/sumenep-matamadura-mono.svg",
  "sumenep-matamadura-mono-white": "/brand/sumenep-matamadura-mono-white.svg",
};

/**
 * Logo SUMENEP – Mata Madura. Single source: public/brand/*.svg, generated by
 * scripts/build-brand.mjs. Intrinsic width/height prevent layout shift.
 */
export function Logo({
  variant = "sumenep-matamadura-stacked",
  className,
  eager = false,
  alt = "SUMENEP – Mata Madura",
}: {
  variant?: Variant;
  className?: string;
  eager?: boolean;
  alt?: string;
}) {
  const { w, h } = meta[variant];
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static SVG brand asset
    <img
      src={FILES[variant]}
      width={w}
      height={h}
      alt={alt}
      className={className}
      loading={eager ? "eager" : "lazy"}
      fetchPriority={eager ? "high" : undefined}
      decoding="async"
    />
  );
}
